def factorize(n):
    f = []
    d = 2
    m = n
    while d * d <= m:
        cnt = 0
        while m % d == 0:
            m //= d
            cnt += 1
        if cnt > 0:
            f.append((d, cnt))
        d += 1
    if m > 1:
        f.append((m, 1))
    return f

def has_forbidden(x, base, F):
    # x is positive
    while x > 0:
        r = x % base
        if r in F:
            return True
        x //= base
    return False

def build_divisor_exponent_list(a_list, n):
    # Returns list of exponent tuples for divisors of (prod p_i^{a_i})^n
    ranges = [range(0, a * n + 1) for a in a_list]
    exps = []
    def rec(idx, cur):
        if idx == len(ranges):
            exps.append(tuple(cur))
            return
        for e in ranges[idx]:
            cur.append(e)
            rec(idx + 1, cur)
            cur.pop()
    rec(0, [])
    return exps

